void GraphViewBase::setupScreen()
{
    performanceText.initialize();
}

void GraphViewBase::radioButtonSelectedCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &temperatureButton)
    {
        //temperatureButtonSelected
        //When temperatureButton selected call virtual function
        //Call temperatureButtonSelected
        temperatureButtonSelected();
    }
    if (&src == &fanButton)
    {
        //fanButtonSelected
        //When fanButton selected call virtual function
        //Call fanButtonSelected
        fanButtonSelected();
    }
    if (&src == &humidityButton)
    {
        //humidityButtonSelected
        //When humidityButton selected call virtual function
        //Call humidityButtonSelected
        humidityButtonSelected();
    }
    if (&src == &livingRoomButton)
    {
        //livingRoomButtonSelected
        //When livingRoomButton selected call virtual function
        //Call roomChanged
        roomChanged();
    }
    if (&src == &bedRoomButton)
    {
        //bedRoomButtonSelected
        //When bedRoomButton selected call virtual function
        //Call roomChanged
        roomChanged();
    }
    if (&src == &kitchenButton)
    {
        //kitchenButtonSelected
        //When kitchenButton selected call virtual function
        //Call roomChanged
        roomChanged();
    }
}

void GraphViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &closeButton)
    {
        //closeButtonClicked
        //When closeButton clicked change screen to Main
        //Go to Main with no screen transition
        application().gotoMainScreenNoTransition();
    }
}

void GraphViewBase::flexButtonCallbackHandler(const touchgfx::AbstractButtonContainer& src)
{
    if (&src == &fahrenheitToggle)
    {
        //fahrenheitToggleClicked
        //When fahrenheitToggle clicked call virtual function
        //Call fahrenheitToggleClicked
        fahrenheitToggleClicked();
    }
}
